import requests

ERROR_MAP = {401: "access denied", 404: "missing resource", 500: "server error"}

def call_api(path, headers=None):
    resp = requests.get("https://api.dojo.dev" + path, headers=headers)
    if resp.status_code == 200:
        return {"ok": True, "data": resp.json()}
    label = ERROR_MAP.get(resp.status_code, f"error {resp.status_code}")
    try:
        detail = resp.json().get("error", resp.text)
    except requests.exceptions.JSONDecodeError:
        detail = resp.text
    return {"ok": False, "message": f"{label}: {detail}"}

import requests

def collect_users():
    users = {}
    page = 1
    while True:
        resp = requests.get("https://api.dojo.dev/users", params={"page": page})
        if resp.status_code != 200:
            raise RuntimeError(f"page {page} failed: status {resp.status_code}")
        data = resp.json()["data"]
        if not data:
            return users
        for u in data:
            users[u["name"]] = u["team"]
        page += 1

