import requests

def list_models(page_limit=10):
    names = []
    cursor = None
    for _ in range(page_limit):
        params = {} if cursor is None else {"cursor": cursor}
        resp = requests.get("https://api.dojo.dev/models", params=params)
        body = resp.json()
        for m in body["models"]:
            names.append(m["name"])
        next_cursor = body["next_cursor"]
        if next_cursor is None:
            return names
        if next_cursor == cursor:
            raise RuntimeError("pagination stuck in a loop: repeated cursor")
        cursor = next_cursor
    raise RuntimeError(f"hit the limit of {page_limit} pages without finishing")

