def smart_retry(path, max_attempts, base):
    resp = None
    for attempt in range(max_attempts):
        resp = requests.get("https://api.dojo.dev" + path)
        if resp.status_code not in (429, 500):
            return resp
        if attempt == max_attempts - 1:
