import requests

class RetriesExhausted(Exception):
    def __init__(self, history):
        super().__init__(f"{len(history)} attempt(s) failed: {history}")
        self.history = history

def fetch_or_blow_up(path, max_attempts):
    history = []
    for _ in range(max_attempts):
        resp = requests.get("https://api.dojo.dev" + path)
        if resp.status_code == 200:
            return resp.json()
        history.append(resp.status_code)
    raise RetriesExhausted(history)

