import requests
import time

def retry_with_budget(path, budget_s, base):
    start = time.monotonic()
    attempt = 0
    while True:
        resp = requests.get("https://api.dojo.dev" + path)
        if resp.status_code == 200:
            return resp.json()
        if resp.status_code not in (429, 500):
            return None
        wait = base * (2 ** attempt) + 0.1 * attempt
        if (time.monotonic() - start) + wait > budget_s:
            return None
        time.sleep(wait)
        attempt += 1

import asyncio
import requests

async def probe_routes(paths):
    async def one(path):
        resp = await requests.aget("https://api.dojo.dev" + path)
        return resp.json()

    results = await asyncio.gather(
        *[one(p) for p in paths], return_exceptions=True
    )
    bodies = []
    failures = 0
    for r in results:
        if isinstance(r, Exception):
            failures += 1
        else:
            bodies.append(r)
    return {"bodies": bodies, "failures": failures}

