def most_similar_index(matrix, query):
    query = np.array(query, dtype=float)
    query_norm = np.linalg.norm(query)
    scores = []
    for row in matrix:
        v = np.array(row, dtype=float)
        scores.append(float(np.dot(v, query) / (np.linalg.norm(v) * query_norm)))
    return int(np.argmax(scores))

